// Local smoke test harness for the chat room (no auth). Run through scripts/chat-room-smoke.mjs.
export {ChatRoom} from '../../lib/chat-room';
export default {async fetch(request:Request,env:{CHAT_ROOM:DurableObjectNamespace}){
 const url=new URL(request.url),room=env.CHAT_ROOM.get(env.CHAT_ROOM.idFromName(url.searchParams.get('club')??'a'));
 return room.fetch(new Request('https://room'+url.pathname,{method:request.method,headers:(()=>{const h=new Headers(request.headers);const p=url.searchParams.get('player');if(p)h.set('x-chat-player',p);return h;})(),body:request.method==='POST'?request.body:undefined}));
}};
